insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9445, 31, 'BAföG-Bedarfssätze und Wohnkostenpauschale automatisch an Lebenshaltungskosten anpassen (Bund)', 'Verhindert, dass das BAföG zwischen Reformen real an Wert verliert (DIW empfiehlt Indexierung); Bund ist zuständig. Zuschüsse wirken laut Studien nur klein positiv auf Studienverlauf, und die Anpassung erhöht das Niveau nicht über den heutigen Stand.', 'gemischt', 'https://www.diw.de/de/diw_01.c.87747.de/bafoeg-reform_hat_kaum_auswirkungen_auf_die_studienaufnahme.html', 'bund', null, true, 'blind'),
  (9446, 31, 'BAföG elternunabhängig und als Vollzuschuss für alle Studierenden (Bund)', 'Mehr Geförderte und keine Schulden würden den Zwang zum Nebenjob deutlich senken; Studien sehen die heutige Bedarfsdeckung als unzureichend. Dagegen: sehr hohe, ungeklärte Kosten und Mitnahme durch Studierende aus wohlhabenden Familien.', 'gemischt', 'https://www.studierendenwerke.de/fileadmin/api/files/210928_fibs_entwicklung_der_einnahmen_von_studierenden_210927_final.pdf', 'bund', null, true, 'blind'),
  (9447, 31, 'Studien- und Bildungskredite ausbauen und Konditionen absichern (Bund)', 'Kredite schließen kurzfristig Finanzierungslücken und sind leicht umsetzbar; sie werden aber nur von wenigen Studierenden genutzt und verlagern die Belastung in Schulden nach dem Abschluss.', 'gemischt', 'https://www.t-online.de/finanzen/beruf-karriere/bildung/id_90444520/60-prozent-mehr-vertraege-zahl-der-studien-neukredite-steigt-sprunghaft-an.html', 'bund', null, true, 'blind'),
  (9448, 31, 'Bundesförderung für Wohnheime von Studierenden und Auszubildenden verstetigen und erhöhen (Bund)', 'Wohnheimplätze sind deutlich günstiger als der freie Markt, es fehlen laut IW über 200.000 Plätze; der Bund finanziert bereits ein Programm. Dagegen: Bau dauert Jahre und erreicht nur einen Teil der Studierenden und Auszubildenden.', 'belegt', 'https://www.iwkoeln.de/presse/iw-nachrichten/philipp-deschermeier-bundesweit-fehlen-mehr-als-200000-wohnheimplaetze-fuer-studenten.html', 'bund', null, true, 'blind'),
  (9449, 31, 'Gesetzliche Mindestausbildungsvergütung anheben (Bund)', 'Hebt die Vergütung genau in Branchen und Regionen mit niedrigen Sätzen (Handwerk, Osten, 7-10 % der Verträge), Bund regelt das im BBiG. Dagegen: Betriebe warnen vor weniger Ausbildungsplätzen; die Wirkung darauf ist noch nicht evaluiert.', 'gemischt', 'https://www.bibb.de/de/pressemitteilung_199964.php', 'bund', null, true, 'blind')
